package site.hsu.hub.recruitment.adapter.out.persistence;import jakarta.persistence.*;
@Entity@Table(name="form_steps")public class FormStepEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="form_id",nullable=false)private Long formId;@Column(nullable=false,length=100)private String title;@Column(name="display_order",nullable=false)private int order;protected FormStepEntity(){}public FormStepEntity(Long form,String title,int order){formId=form;this.title=title;this.order=order;}public Long id(){return id;}public String title(){return title;}public int order(){return order;}}
